import { expect, describe, test, jest } from '@jest/globals';
import { getUserData } from './getUserData';

const mockFindUser = jest.fn<(id: string) => Promise<{ id: string } | null>>();

const setupUser = ({ found = true }: { found?: boolean } = {}) => {
	if (found) {
		mockFindUser.mockResolvedValue({ id: '1' });
	} else {
		mockFindUser.mockRejectedValue(new Error('Not found'));
	}

	return { findUser: mockFindUser };
};

describe('getUserData', () => {
	test('rejects when the user does not exist', async () => {
		const { findUser } = setupUser({ found: false });

		await expect(getUserData({ findUser, userId: '999' })).rejects.toThrow('Not found');
	});
});

import { expect, describe, test, jest } from '@jest/globals';
import { getUserData } from './getUserData';

const mockFindUser = jest.fn<(id: string) => Promise<{ id: string } | null>>();

describe('getUserData', () => {
	test('rejects when the user does not exist', () => {
		mockFindUser.mockImplementation(() => Promise.reject(new Error('Not found')));

		// nothing is awaited, so the assertion runs before the rejection lands and
		// the test passes whatever the unit does
		getUserData({ findUser: mockFindUser, userId: '999' }).catch((error: Error) => {
			expect(error.message).toBe('Not found');
		});
	});
});

interface ConstructorParams {
	baseUrl: string;
	retries?: number;
}

// Criteria (a) and (b) together: injected configuration every method reads, and
// a retry budget that changes as calls are made.
export class HttpClient {
	private readonly baseUrl: string;

	private remaining: number;

	constructor({ baseUrl, retries = 3 }: ConstructorParams) {
		this.baseUrl = baseUrl;
		this.remaining = retries;
	}

	get({ path }: { path: string }): string {
		this.remaining -= 1;

		return `GET ${this.baseUrl}${path}`;
	}

	post({ path }: { path: string }): string {
		this.remaining -= 1;

		return `POST ${this.baseUrl}${path}`;
	}

	getRemainingRetries(): number {
		return this.remaining;
	}
}

interface Params {
	rows: Array<{ label: string; amount: number }>;
}

// The one-method class rewritten as what it always was.
export const formatReportRows = ({ rows }: Params): string => rows.map((row) => `${row.label}: ${row.amount}`).join('\n');

// A module wearing a costume: the class binds no state and exists only to put
// a `ConfigPaths.` prefix in front of three values.
export class ConfigPaths {
	static readonly root = '.lightsout';

	static readonly config = '.lightsout/config.json';

	static forRun({ id }: { id: string }): string {
		return `.lightsout/runs/${id}`;
	}
}

interface Row {
	label: string;
	amount: number;
}

// A function with a hat on: one method, nothing held between calls, and every
// caller writing `new ReportGenerator().execute(...)` to reach it.
export class ReportGenerator {
	execute({ rows }: { rows: Row[] }): string {
		return rows.map((row) => `${row.label}: ${row.amount}`).join('\n');
	}
}

export interface Invoice {
	id: string;
}

rules.prose:
## Use a union type paired with a `const` object

For a set of named string values, use a **union type** backed by a `const` object. The `const` object is the single source of truth; the union is derived from it. Consumers reference the object (`Action.Add`), never raw string literals.

✅ GOOD: `const` object + derived union

**`common/constants/Action.ts`**

```typescript
export const Action = {
	Add: 'add',
	Remove: 'remove',
	List: 'list',
	Update: 'update',
} as const;

export type Action = (typeof Action)[keyof typeof Action];
```

```typescript
// consumer — references the object, not a raw string
doThing(Action.Add);
```

❌ BAD: bare union, values redefined at every call site

```typescript
export type Action = 'add' | 'remove' | 'list' | 'update';

// consumers retype raw literals — the source of truth is now "everywhere"
doThing('add');
```

