interface RunRecorder {
	record: (params: { step: string }) => void;
}

const createRunRecorder = (): RunRecorder => {
	const steps: string[] = [];

	return { record: ({ step }) => steps.push(step) };
};

// The shared part is held as a value and delegated to — visible at the seam.
export class RefactorRun implements RunRecorder {
	private readonly recorder = createRunRecorder();

	record({ step }: { step: string }): void {
		this.recorder.record({ step });
	}

	decline({ step }: { step: string }): void {
		this.recorder.record({ step: `declined:${step}` });
	}
}

// The one licensed base: subclassing is the platform's only way to make a
// typed, instanceof-checkable error.
export class RunLockError extends Error {}

// Error-family chains stay licensed too.
export class StaleRunLockError extends RunLockError {}

class RunState {
	protected steps: string[] = [];

	record({ step }: { step: string }): void {
		this.steps.push(step);
	}
}

export class RefactorRun extends RunState {
	decline({ step }: { step: string }): void {
		this.record({ step: `declined:${step}` });
	}
}

interface ConstructorParams {
	baseUrl: string;
}

// The stateless half is a co-located helper, so the class surface is only what
// genuinely needs the injected base url.
const buildQuery = ({ query }: { query: Record<string, string> }) =>
	Object.entries(query)
		.map(([key, value]) => `${key}=${value}`)
		.join('&');

export class HttpClient {
	private readonly baseUrl: string;

	constructor({ baseUrl }: ConstructorParams) {
		this.baseUrl = baseUrl;
	}

	get({ path, query }: { path: string; query: Record<string, string> }): string {
		return `${this.baseUrl}${path}?${buildQuery({ query })}`;
	}
}

interface ConstructorParams {
	baseUrl: string;
}

// `buildQuery` touches no state — it is on the surface only because it was
// written where the class was, and every consumer now sees it as API.
export class HttpClient {
	private readonly baseUrl: string;

	constructor({ baseUrl }: ConstructorParams) {
		this.baseUrl = baseUrl;
	}

	get({ path, query }: { path: string; query: Record<string, string> }): string {
		return `${this.baseUrl}${path}?${this.buildQuery({ query })}`;
	}

	buildQuery({ query }: { query: Record<string, string> }): string {
		return Object.entries(query)
			.map(([key, value]) => `${key}=${value}`)
			.join('&');
	}
}

rules.prose:
## Syntax & Style

- Constructor takes an object argument, destructured; declare a `ConstructorParams` interface for it.
- **Instance methods** use inline object types for their params — not separate interfaces (keeps the signature self-contained, avoids interface-file sprawl).
- Public methods of an exported class declare return types; `private` methods infer (see [return-types.md](../typescript/return-types.md)). Interface-pinned methods need not restate the type.
- Export the class as a named export on the line it is defined.

```typescript
interface ConstructorParams {
	name: string;
	isActive?: boolean;
}

export class Person {
	private readonly name: string;
	private isActive: boolean;

	constructor({ name, isActive = true }: ConstructorParams) {
		this.name = name;
		this.isActive = isActive;
	}

	greet(): string {
		return `Hello, my name is ${this.name}.`;
	}

	setActiveStatus({ status }: { status: boolean }): void {
		this.isActive = status;
	}
}
```

