// `renderGreeting` is published by the package entry and `buildGreeting` used
// by it — every export in the package has something that consumes it.
export { renderGreeting } from './feature/renderGreeting';

import { createRootRoute, createRouter } from '@tanstack/react-router';

const routeTree = createRootRoute();

// The Start plugin resolves this file by convention. Nothing in the app imports
// `getRouter` and no entry publishes it — which is exactly what makes it read
// as dead to a check that does not know the framework named it.
export const getRouter = () => createRouter({ routeTree });

// Nothing in this repo mentions `buildGreeting` — no module, no entry, no
// test. Version control has its history; the file does not need to keep it.
export const buildGreeting = ({ name }: { name: string }): string => `Hello, ${name}.`;

// The package entry publishes `renderGreeting`, so it is used. Nothing
// publishes or imports the greeting builder beside it in feature/.
export { renderGreeting } from './feature/renderGreeting';

rules.prose:
## Derived Lookup Maps May Co-Locate

A lookup map keyed by the union (`Record<Action, …>`) may live in the same file as the `const` object — the two are tautologically coupled, so every change to one changes the other.

```typescript
export const LogLevel = {
	Debug: 'debug',
	Info: 'info',
	Error: 'error',
} as const;

export type LogLevel = (typeof LogLevel)[keyof typeof LogLevel];

export const logLevelLabels: Record<LogLevel, string> = {
	[LogLevel.Debug]: 'Debug',
	[LogLevel.Info]: 'Info',
	[LogLevel.Error]: 'Error',
};
```

An unrelated constant that merely *uses* the union goes in `constants/` as usual.

