			{Object.entries(byAssignee).map(([assignee, assigned]) => (
				<div key={assignee}>
					<h3>{assignee}</h3>
					<ul>
						{assigned.map((issue) => (
							<li key={issue.id}>
								{issue.title} — {issue.state}
							</li>
						))}
					</ul>
				</div>
			))}
